//! Binary-search primitives shared by the sorted containers.
//!
//! Both functions take a projection so that they work over a slice of entries
//! (`(K, V)` pairs) as well as over a slice of plain values, and both keep the
//! same contract as the C++ `std::lower_bound` / `std::upper_bound` pair: the
//! slice must already be ordered by the projected key.

use std::cmp::Ordering;

/// Index of the first element whose key is not less than `target`.
///
/// Equivalent to `std::lower_bound`: every element before the returned index
/// compares less than `target`, and inserting there keeps the slice sorted
/// while placing the new element *before* any equal keys.
pub fn bisect_left<T, K, F>(slice: &[T], target: &K, key: F) -> usize
where
    K: Ord,
    F: Fn(&T) -> &K,
{
    let mut lo = 0;
    let mut hi = slice.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match key(&slice[mid]).cmp(target) {
            Ordering::Less => lo = mid + 1,
            _ => hi = mid,
        }
    }
    lo
}

/// Index of the first element whose key is greater than `target`.
///
/// Equivalent to `std::upper_bound`: inserting there keeps the slice sorted
/// while placing the new element *after* any equal keys.
pub fn bisect_right<T, K, F>(slice: &[T], target: &K, key: F) -> usize
where
    K: Ord,
    F: Fn(&T) -> &K,
{
    let mut lo = 0;
    let mut hi = slice.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match key(&slice[mid]).cmp(target) {
            Ordering::Greater => hi = mid,
            _ => lo = mid + 1,
        }
    }
    lo
}

