//! A sorted sequence of values, kept ordered on every insertion.

use std::ops::Index;

use super::bisect::{bisect_left, bisect_right};

/// A list that always stays in ascending order.
///
/// Duplicates are allowed and are kept in insertion order relative to each
/// other, because [`SortedList::insert`] places a new value after any equal
/// values already present. Lookups are `O(log n)`; insertion and removal are
/// `O(log n)` searches followed by an `O(n)` shift of the tail.
#[derive(Clone, Debug, Default, PartialEq, Eq, PartialOrd, Ord)]
pub struct SortedList<T: Ord> {
    items: Vec<T>,
}

impl<T: Ord> SortedList<T> {
    pub fn new() -> Self {
        SortedList { items: Vec::new() }
    }

    pub fn with_capacity(capacity: usize) -> Self {
        SortedList {
            items: Vec::with_capacity(capacity),
        }
    }

    /// Adopts a vector that is already in ascending order, skipping the sort.
    ///
    /// The ordering is checked in debug builds only, so callers are
    /// responsible for it in release builds.
    pub fn from_sorted_vec(items: Vec<T>) -> Self {
        debug_assert!(
            items.windows(2).all(|pair| pair[0] <= pair[1]),
            "from_sorted_vec called with an unsorted vector"
        );
        SortedList { items }
    }

    /// Sorts `items` and takes ownership of the result.
    pub fn from_vec(mut items: Vec<T>) -> Self {
        items.sort();
        SortedList { items }
    }

    pub fn len(&self) -> usize {
        self.items.len()
    }

    pub fn is_empty(&self) -> bool {
        self.items.is_empty()
    }

    pub fn clear(&mut self) {
        self.items.clear();
    }

    /// Inserts `value` after any equal values and returns its index.
    pub fn insert(&mut self, value: T) -> usize {
        let index = self.bisect_right(&value);
        self.items.insert(index, value);
        index
    }

    /// Removes one occurrence of `value`, reporting whether it was there.
    pub fn remove(&mut self, value: &T) -> bool {
        match self.index_of(value) {
            Some(index) => {
                self.items.remove(index);
                true
            }
            None => false,
        }
    }

    /// Removes and returns the value at `index`.
    ///
    /// # Panics
    /// Panics if `index` is out of bounds.
    pub fn remove_at(&mut self, index: usize) -> T {
        self.items.remove(index)
    }

    /// Index of the first occurrence of `value`, if present.
    pub fn index_of(&self, value: &T) -> Option<usize> {
        let index = self.bisect_left(value);
        if index < self.items.len() && self.items[index] == *value {
            Some(index)
        } else {
            None
        }
    }

    pub fn contains(&self, value: &T) -> bool {
        self.index_of(value).is_some()
    }

    /// Number of occurrences of `value`.
    pub fn count(&self, value: &T) -> usize {
        self.bisect_right(value) - self.bisect_left(value)
    }

    /// Index of the first value not less than `value`.
    pub fn bisect_left(&self, value: &T) -> usize {
        bisect_left(&self.items, value, |item| item)
    }

    /// Index of the first value greater than `value`.
    pub fn bisect_right(&self, value: &T) -> usize {
        bisect_right(&self.items, value, |item| item)
    }

    pub fn get(&self, index: usize) -> Option<&T> {
        self.items.get(index)
    }

    pub fn first(&self) -> Option<&T> {
        self.items.first()
    }

    pub fn last(&self) -> Option<&T> {
        self.items.last()
    }

    pub fn iter(&self) -> std::slice::Iter<'_, T> {
        self.items.iter()
    }

    pub fn as_slice(&self) -> &[T] {
        &self.items
    }

    pub fn into_vec(self) -> Vec<T> {
        self.items
    }
}

impl<T: Ord> Index<usize> for SortedList<T> {
    type Output = T;

    fn index(&self, index: usize) -> &T {
        &self.items[index]
    }
}

impl<T: Ord> FromIterator<T> for SortedList<T> {
    fn from_iter<I: IntoIterator<Item = T>>(iter: I) -> Self {
        SortedList::from_vec(iter.into_iter().collect())
    }
}

impl<T: Ord> IntoIterator for SortedList<T> {
    type Item = T;
    type IntoIter = std::vec::IntoIter<T>;

    fn into_iter(self) -> Self::IntoIter {
        self.items.into_iter()
    }
}

impl<'a, T: Ord> IntoIterator for &'a SortedList<T> {
    type Item = &'a T;
    type IntoIter = std::slice::Iter<'a, T>;

    fn into_iter(self) -> Self::IntoIter {
        self.items.iter()
    }
}

