/// `std::atoi`: parse a leading decimal integer, yielding 0 when there is none.
///
/// Reproduces glibc's behaviour rather than Rust's stricter parsing, because the
/// program feeds it raw `argv` text:
///
/// * leading whitespace is skipped and an optional sign is accepted;
/// * parsing stops at the first non-digit, so `"7xyz"` is 7 and `"3.9"` is 3;
/// * trailing garbage or an empty/non-numeric string yields 0;
/// * glibc implements `atoi` as `(int) strtol(...)`, so a value too large for
///   `long` saturates and the result is then truncated to `int`. `2147483648`
///   therefore comes back as `-2147483648`, not as `INT_MAX`.
pub fn atoi(text: &str) -> i32 {
    let bytes = text.as_bytes();
    let mut pos = 0;

    // `isspace` in the C locale, which also counts a vertical tab.
    while pos < bytes.len() && (bytes[pos].is_ascii_whitespace() || bytes[pos] == b'\x0b') {
        pos += 1;
    }

    let mut negative = false;
    if pos < bytes.len() && (bytes[pos] == b'+' || bytes[pos] == b'-') {
        negative = bytes[pos] == b'-';
        pos += 1;
    }

    let mut magnitude: i64 = 0;
    let mut saturated = false;
    while pos < bytes.len() && bytes[pos].is_ascii_digit() {
        let digit = i64::from(bytes[pos] - b'0');
        match magnitude.checked_mul(10).and_then(|acc| acc.checked_add(digit)) {
            Some(next) if !saturated => magnitude = next,
            // Keep consuming digits after overflow, as `strtol` does.
            _ => saturated = true,
        }
        pos += 1;
    }

    let wide = if saturated {
        if negative {
            i64::MIN
        } else {
            i64::MAX
        }
    } else if negative {
        -magnitude
    } else {
        magnitude
    };

    wide as i32
}

