    let mut n: i32 = 18;
    if args.len() > 1 {
        n = atoi(&args[1]);
    }

    let mut m: SortedMap<(i32, i32), String> = SortedMap::new();
    for i in 0..n {
        let key = (i, i * 2);
        m.insert(key, format!("value_{}", i));
    }

    println!("{}", m.len());

    let test_key1 = (3, 6);
    let test_key2 = (5, 10);

    println!("{}", u8::from(m.contains_key(&test_key1)));
    println!("{}", u8::from(m.contains_key(&test_key2)));

    // As in C++, reading through `operator[]` inserts an empty string when the
    // key is absent, so this can grow the map by one entry.
    println!("{}", m.entry_or_default(&test_key1));

    *m.entry_or_default(&test_key1) = "modified".to_string();
    println!("{}", m.entry_or_default(&test_key1));

    let keys = m.keys();
    let values = m.values();

    println!("{}", keys.len());
    println!("{}", values.len());

    for i in 0..4 {
        let key_to_remove = (i, i * 2);
        m.remove(&key_to_remove);
    }

    println!("{}", m.len());

    let it = m.find(&(6, 12));
    if it != m.end() {
        println!("{}", m.value_at(it));
    }

    let lb = m.lower_bound(&(7, 14));
    if lb != m.end() {
        println!("{}", m.key_at(lb).0);
    }

    let ub = m.upper_bound(&(7, 14));
    if ub != m.end() {
        println!("{}", m.key_at(ub).0);
    }

    let mut m2: SortedMap<(i32, i32), String> = SortedMap::new();
    for i in 0..n / 2 {
        let key = (i + 10, (i + 10) * 2);
        m2.insert(key, format!("other_{}", i));
    }

    sortedcontainers::update(&mut m, &m2);

    println!("{}", m.len());
    println!("{}", u8::from(m.contains_key(&(12, 24))));

    let range = m.equal_range(&(8, 16));
    let mut count = 0;
    for _ in range.0..range.1 {
        count += 1;
    }
    println!("{}", count);

    println!("{}", m.get_or(&(100, 200), "default".to_string()));

    m.clear();

    println!("{}", m.len());
    println!("{}", u8::from(m.is_empty()));
}

