//! An associative container that keeps its keys in ascending order.

use std::cmp::Ordering;

use super::bisect::{bisect_left, bisect_right};
use super::sorted_list::SortedList;

/// A map whose entries are stored contiguously in ascending key order.
///
/// # Cursors instead of iterators
///
/// The C++ container hands out bidirectional iterators, compared against
/// `end()` and dereferenced with `->first` / `->second`. Rust cannot express
/// that shape without either unsafe code or borrow-splitting gymnastics, so the
/// equivalent operations here return a *cursor*: a `usize` position in key
/// order. [`SortedMap::end`] plays the role of the past-the-end iterator, and
/// [`SortedMap::key_at`] / [`SortedMap::value_at`] play the role of `->first`
/// and `->second`.
///
/// ```text
/// C++                              Rust
/// auto it = m.find(k);             let it = m.find(&k);
/// if (it != m.end())               if it != m.end()
///     use(it->second);                 use(m.value_at(it));
/// ```
///
/// A cursor is only valid until the next mutation, exactly as a C++ iterator
/// into this container would be.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct SortedMap<K: Ord, V> {
    /// Entries ordered by key; keys are unique.
    entries: Vec<(K, V)>,
}

impl<K: Ord, V> SortedMap<K, V> {
    pub fn new() -> Self {
        SortedMap {
            entries: Vec::new(),
        }
    }

    pub fn with_capacity(capacity: usize) -> Self {
        SortedMap {
            entries: Vec::with_capacity(capacity),
        }
    }

    pub fn len(&self) -> usize {
        self.entries.len()
    }

    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    pub fn clear(&mut self) {
        self.entries.clear();
    }

    /// Inserts `value` under `key`, returning the value it displaced.
    pub fn insert(&mut self, key: K, value: V) -> Option<V> {
        match self.locate(&key) {
            Ok(index) => Some(std::mem::replace(&mut self.entries[index].1, value)),
            Err(index) => {
                self.entries.insert(index, (key, value));
                None
            }
        }
    }

    /// Removes `key`, returning its value if the map held one.
    ///
    /// Mirrors the C++ `erase`.
    pub fn remove(&mut self, key: &K) -> Option<V> {
        match self.locate(key) {
            Ok(index) => Some(self.entries.remove(index).1),
            Err(_) => None,
        }
    }

    pub fn contains_key(&self, key: &K) -> bool {
        self.locate(key).is_ok()
    }

    pub fn get(&self, key: &K) -> Option<&V> {
        match self.locate(key) {
            Ok(index) => Some(&self.entries[index].1),
            Err(_) => None,
        }
    }

    pub fn get_mut(&mut self, key: &K) -> Option<&mut V> {
        match self.locate(key) {
            Ok(index) => Some(&mut self.entries[index].1),
            Err(_) => None,
        }
    }

    /// Value stored under `key`, or `default` when the key is absent.
    ///
    /// Mirrors the C++ `get(key, default)`: the map is left untouched either
    /// way, and the result is returned by value.
    pub fn get_or(&self, key: &K, default: V) -> V
    where
        V: Clone,
    {
        match self.get(key) {
            Some(value) => value.clone(),
            None => default,
        }
    }

    /// Mutable access to `key`, inserting `V::default()` first if it is absent.
    ///
    /// This is the C++ `operator[]`, including its side effect: merely reading
    /// through it grows the map when the key was missing.
    pub fn entry_or_default(&mut self, key: &K) -> &mut V
    where
        K: Clone,
        V: Default,
    {
        let index = match self.locate(key) {
            Ok(index) => index,
            Err(index) => {
                self.entries.insert(index, (key.clone(), V::default()));
                index
            }
        };
        &mut self.entries[index].1
    }

    /// All keys, in ascending order.
    pub fn keys(&self) -> SortedList<K>
    where
        K: Clone,
    {
        SortedList::from_sorted_vec(self.entries.iter().map(|entry| entry.0.clone()).collect())
    }

    /// All values, ordered by their keys.
    pub fn values(&self) -> Vec<V>
    where
        V: Clone,
    {
        self.entries.iter().map(|entry| entry.1.clone()).collect()
    }

    pub fn iter(&self) -> impl Iterator<Item = (&K, &V)> {
        self.entries.iter().map(|entry| (&entry.0, &entry.1))
    }

    /// The past-the-end cursor, i.e. C++ `end()`.
    pub fn end(&self) -> usize {
        self.entries.len()
    }

    /// Cursor to `key`, or [`SortedMap::end`] when it is absent.
    pub fn find(&self, key: &K) -> usize {
        match self.locate(key) {
            Ok(index) => index,
            Err(_) => self.end(),
        }
    }

    /// Cursor to the first key not less than `key`.
    pub fn lower_bound(&self, key: &K) -> usize {
        bisect_left(&self.entries, key, |entry| &entry.0)
    }

    /// Cursor to the first key greater than `key`.
    pub fn upper_bound(&self, key: &K) -> usize {
        bisect_right(&self.entries, key, |entry| &entry.0)
    }

    /// Half-open cursor range covering `key`; empty when the key is absent.
    pub fn equal_range(&self, key: &K) -> (usize, usize) {
        let lower = self.lower_bound(key);
        let upper = if lower < self.entries.len() && self.entries[lower].0 == *key {
            lower + 1
        } else {
            lower
        };
        (lower, upper)
    }

    /// Key at `cursor`, i.e. C++ `it->first`.
    ///
    /// # Panics
    /// Panics if `cursor` is not a valid position, which is the Rust-side
    /// equivalent of dereferencing `end()`.
    pub fn key_at(&self, cursor: usize) -> &K {
        &self.entries[cursor].0
    }

    /// Value at `cursor`, i.e. C++ `it->second`.
    ///
    /// # Panics
    /// Panics if `cursor` is not a valid position.
    pub fn value_at(&self, cursor: usize) -> &V {
        &self.entries[cursor].1
    }

    /// Both halves of the entry at `cursor`, i.e. C++ `*it`.
    ///
    /// # Panics
    /// Panics if `cursor` is not a valid position.
    pub fn entry_at(&self, cursor: usize) -> (&K, &V) {
        let entry = &self.entries[cursor];
        (&entry.0, &entry.1)
    }

    /// Copies every entry of `other` into `self`, overwriting shared keys.
    ///
    /// Both sides are already ordered, so this is a single linear merge rather
    /// than one binary-search insertion per entry.
    pub fn update(&mut self, other: &SortedMap<K, V>)
    where
        K: Clone,
        V: Clone,
    {
        let mine = std::mem::take(&mut self.entries);
        let mut merged = Vec::with_capacity(mine.len() + other.entries.len());
        let mut mine = mine.into_iter().peekable();
        let mut theirs = other.entries.iter().peekable();

        loop {
            let order = match (mine.peek(), theirs.peek()) {
                (Some(lhs), Some(rhs)) => lhs.0.cmp(&rhs.0),
                (Some(_), None) => Ordering::Less,
                (None, Some(_)) => Ordering::Greater,
                (None, None) => break,
            };
            match order {
                Ordering::Less => merged.push(mine.next().unwrap()),
                Ordering::Greater => {
                    let (key, value) = theirs.next().unwrap();
                    merged.push((key.clone(), value.clone()));
                }
                // Same key on both sides: `other` wins, so drop ours.
                Ordering::Equal => {
                    mine.next();
                    let (key, value) = theirs.next().unwrap();
                    merged.push((key.clone(), value.clone()));
                }
            }
        }

        self.entries = merged;
    }

    /// `Ok(index)` when `key` is present, `Err(insertion point)` when it is not.
    fn locate(&self, key: &K) -> Result<usize, usize> {
        let index = self.lower_bound(key);
        if index < self.entries.len() && self.entries[index].0 == *key {
            Ok(index)
        } else {
            Err(index)
        }
    }
}

impl<K: Ord, V> FromIterator<(K, V)> for SortedMap<K, V> {
    fn from_iter<I: IntoIterator<Item = (K, V)>>(iter: I) -> Self {
        let mut map = SortedMap::new();
        for (key, value) in iter {
            map.insert(key, value);
        }
        map
    }
}

impl<K: Ord, V> IntoIterator for SortedMap<K, V> {
    type Item = (K, V);
    type IntoIter = std::vec::IntoIter<(K, V)>;

    fn into_iter(self) -> Self::IntoIter {
        self.entries.into_iter()
    }
}
